<div class="card"><div class="page-title clearfix"><h4><?php echo app_lang('fiscal_invoice_center'); ?></h4></div><div class="card-body">
<div class="row mb15"><div class="col-md-5"><input id="fiscal-invoice-search" class="form-control" placeholder="<?php echo app_lang('search'); ?>"></div><div class="col-md-3"><?php echo form_dropdown('status',[''=>app_lang('all'),'stamped'=>'Timbrada','cancelled'=>'Cancelada','stamped_pdf_pending'=>'PDF pendiente','unknown'=>'Desconocido'],'',"id='fiscal-invoice-status' class='form-control'"); ?></div><div class="col-md-3"><?php echo form_dropdown('pdf',[''=>app_lang('all'),'yes'=>'PDF disponible','no'=>'PDF no disponible'],'',"id='fiscal-invoice-pdf' class='form-control'"); ?></div></div>
<div class="table-responsive"><table id="fiscal-invoices-table" class="display" width="100%"></table></div></div></div><form id="fiscal-pdf-csrf"><?php echo csrf_field(); ?></form>
<script>$(document).ready(function(){var table=$('#fiscal-invoices-table').appTable({source:'<?php echo_uri('fiscal/invoices/list'); ?>',filterParams:{search:'#fiscal-invoice-search',status:'#fiscal-invoice-status',pdf:'#fiscal-invoice-pdf'},columns:[{title:'Serie/Folio'},{title:'Receptor'},{title:'RFC'},{title:'Venta'},{title:'Emisión'},{title:'Subtotal'},{title:'Impuestos'},{title:'Total'},{title:'UUID'},{title:'Estado'},{title:'PDF'},{title:'Timbrado'},{title:'Cancelación'},{title:'<i data-feather=\"menu\" class=\"icon-16\"></i>',class:'text-center option'}]});$('#fiscal-invoice-search').on('keyup',function(){table.appTable({reload:true});});$(document).on('click','.fiscal-generate-pdf',function(){var button=$(this),message='Generar PDF del PAC\n\nSerie: '+button.data('series')+'\nFolio: '+button.data('folio')+'\nUUID: '+button.data('uuid')+'\nPlantilla: '+button.data('template');if(!window.confirm(message))return false;var token=$('#fiscal-pdf-csrf input'),data={};data[token.attr('name')]=token.val();$.post('<?php echo get_uri('fiscal/documents'); ?>/'+button.data('document-id')+'/pdf/generate',data,function(result){if(result.csrf)token.attr('name',result.csrf.name).val(result.csrf.hash);if(result.success){appAlert.success(result.message||'PDF generado correctamente.');table.appTable({reload:true});}else appAlert.error(result.message);},'json');return false;});});</script>
